import 'package:mailer/mailer.dart';
import 'package:mailer/smtp_server.dart';

void main() async {
  var smtpServer = gmail('user@gmail.com', 'appPassword');
  var message = Message()
    ..from = Address('user@gmail.com', 'Your Name')
    ..recipients.add('dest@example.com')
    ..subject = 'Test'
    ..text = 'Hello from Dart!';
  await send(message, smtpServer);
}
